import './Experience.css';
import React from 'react';

function Experience() {

    function filterSelection(c) {
        var x, i;
        x = document.getElementsByClassName("column");
        if (c === "all") c = ""; // Show all items if "all" is selected
    
        // Loop through all elements and hide or show based on the filter
        for (i = 0; i < x.length; i++) {
            w3RemoveClass(x[i], "show");
            if (x[i].className.indexOf(c) > -1) {
                w3AddClass(x[i], "show");
            }
        }
    }
    function w3AddClass(element, name) {
        if (element.className.indexOf(name) === -1) {
            element.className += " " + name;
        }
    }
    
    // Remove the "show" class (hides items)
    function w3RemoveClass(element, name) {
        var arr = element.className.split(" ");
        while (arr.indexOf(name) > -1) {
            arr.splice(arr.indexOf(name), 1);
        }
        element.className = arr.join(" ");
    }
    
    // Highlight active button
    var btnContainer = document.getElementById("myBtnContainer");
    var btns = btnContainer.getElementsByClassName("btn");
    for (var i = 0; i < btns.length; i++) {
        btns[i].addEventListener("click", function () {
            var current = document.getElementsByClassName("active");
            if (current.length > 0) {
                current[0].className = current[0].className.replace(" active", "");
            }
            this.className += " active";
        });
    }
    

  return (
    <div className="Experience">
      <div className='experienceButtonContainer'>
        <button className='experienceButton' 
        onClick={() => filterSelection('Work')}>Work</button>
        <button className='experienceButton'
        onClick={() => filterSelection('Education')}>Education</button>
      </div>

        <div className='ExperienceSection'>
        
        <div className='Work'>

        </div>

        <div className='Education'>

        </div>
    
    
        </div> 


    </div>
  );
}

export default Experience;
